import { createProject, createShape } from '../../src/engine/project';
export function sound() { const rate = 48000, bytes = Buffer.alloc(44 + rate * 2); bytes.write('RIFF'); bytes.writeUInt32LE(bytes.length - 8, 4); bytes.write('WAVEfmt ', 8); bytes.writeUInt32LE(16, 16); bytes.writeUInt16LE(1, 20); bytes.writeUInt16LE(1, 22); bytes.writeUInt32LE(rate, 24); bytes.writeUInt32LE(rate * 2, 28); bytes.writeUInt16LE(2, 32); bytes.writeUInt16LE(16, 34); bytes.write('data', 36); bytes.writeUInt32LE(rate * 2, 40); for (let i = 0; i < rate; i++) bytes.writeInt16LE(Math.round(Math.sin(i / rate * 440 * Math.PI * 2) * 8000), 44 + i * 2); return bytes; }
export function movie() { const p = createProject('blank'); p.name = 'A real movie'; p.width = 64; p.height = 64; p.fps = 12; p.duration = 12; p.camera.x = 32; p.camera.y = 32; p.workArea = { start: 0, end: 11 }; p.background = '#ffffff'; const item = createShape('rectangle', 12, 32); item.fill = '#ff0000'; item.width = 14; item.height = 14; p.items = [item]; p.keyframes[item.id] = [{ id: 'start', frame: 0, easing: 'linear', values: { x: 12 } }, { id: 'end', frame: 11, easing: 'linear', values: { x: 52 } }]; return p; }

